  "Delete Your Account?": "अपना अकाउंट हटाएं?",
  "Your account, rides you organize, Garage, trips and groups will be permanently deleted. Rides you organize are removed for everyone on them. This can’t be undone. If you pay for Pro, cancel it in your Apple subscriptions too.": "आपका अकाउंट, आपकी आयोजित राइड, गैराज, ट्रिप और ग्रुप हमेशा के लिए हटा दिए जाएंगे। आपकी आयोजित राइड उनमें शामिल सभी के लिए हट जाती हैं। इसे वापस नहीं किया जा सकता। अगर आप Pro के लिए भुगतान करते हैं, तो उसे अपने Apple सब्सक्रिप्शन में भी रद्द करें।",
