  "Light is easier to read in bright sun. Match Phone follows your device’s own Dark Mode setting.": "तेज़ धूप में लाइट पढ़ने में आसान है। \"फ़ोन जैसा\" आपके डिवाइस की डार्क मोड सेटिंग के हिसाब से चलता है।",
  "Theme": "थीम",
  "Each theme has a dark and a light version.": "हर थीम का एक डार्क और एक लाइट वर्ज़न है।",
  "Rider status, alerts, trail ratings and your Track Line switch to colors that red-green and blue-yellow color blind riders can tell apart, and each status gets a symbol so color is never the only clue.": "राइडर स्थिति, अलर्ट, ट्रेल रेटिंग और आपकी ट्रैक लाइन ऐसे रंगों में बदल जाती हैं जिन्हें लाल-हरे और नीले-पीले रंगांधता वाले राइडर पहचान सकें, और हर स्थिति को एक चिह्न मिलता है ताकि रंग कभी अकेला संकेत न हो।",
  "Saved on this device. The maps, logo red and logo blue look the same in every theme.": "इस डिवाइस पर सेव है। मैप और लोगो का लाल और नीला हर थीम में एक जैसे दिखते हैं।",
