  "Tap Follow on a ride page to hear when that leader posts a new public ride.": "जब वह लीडर नई सार्वजनिक राइड डाले तब पता चलने के लिए राइड पेज पर फ़ॉलो टैप करें।",
  "No Groups Yet": "अभी कोई ग्रुप नहीं",
  "Make one for the friends you ride with most weekends. Add people you’ve ridden with, or send the group link to anyone else.": "उन दोस्तों के लिए एक ग्रुप बनाएं जिनके साथ आप ज़्यादातर वीकेंड राइड करते हैं। जिनके साथ राइड की है उन्हें जोड़ें, या बाकी सबको ग्रुप लिंक भेजें।",
  "Almost Ready": "लगभग तैयार",
  "Add the backend keys to app/.env (see .env.example), then restart the app.": "बैकएंड कीज़ app/.env में जोड़ें (.env.example देखें), फिर ऐप दोबारा शुरू करें।",
