  "Finish signing in inside the app, or carry on here in the browser.": "ऐप में साइन इन पूरा करें, या यहीं ब्राउज़र में जारी रखें।",
  "Open in the App": "ऐप में खोलें",
  "Continue on the Website": "वेबसाइट पर जारी रखें",
  "Let’s Ride": "चलो राइड करें",
  "Your Email Is Confirmed": "आपका ईमेल कन्फ़र्म हो गया",
  "This link opened somewhere other than where you signed up, so sign in once more with your email and password.": "यह लिंक उस जगह से अलग जगह खुला जहां आपने साइन अप किया था, इसलिए अपने ईमेल और पासवर्ड से एक बार फिर साइन इन करें।",
  "That Link Didn’t Work": "वह लिंक काम नहीं किया",
  "Back to Sign In": "साइन इन पर वापस जाएं",
  "Sign in to earn badges for the rides you lead, join and finish.": "जो राइड आप लीड करते हैं, जिनमें शामिल होते हैं और पूरी करते हैं, उनके बैज पाने के लिए साइन इन करें।",
  "Badges start working with the next server update.": "बैज अगले सर्वर अपडेट से काम करना शुरू करेंगे।",
  "Try Again": "फिर से कोशिश करें",
  "A ride counts once it ends, for riders whose own location track covers at least half a mile. Leading, tail gunning and group rides need at least two riders with a track. Badges are earned on the server from what you really ride, so they can’t be added by hand. OnMyLead Founder and Brand Ambassador are the exceptions: OnMyLead gives them, and they don’t count toward your rank.": "राइड खत्म होने पर गिनी जाती है, उन राइडर के लिए जिनका अपना लोकेशन ट्रैक कम से कम आधा मील हो। लीड करने, टेल गनर बनने और ग्रुप राइड के लिए ट्रैक वाले कम से कम दो राइडर चाहिए। बैज सर्वर पर आपकी असली राइड से मिलते हैं, इसलिए हाथ से नहीं जोड़े जा सकते। OnMyLead Founder और Brand Ambassador अपवाद हैं: ये OnMyLead देता है, और ये आपकी रैंक में नहीं गिने जाते।",
  "Your Rank": "आपकी रैंक",
  "New": "नया",
  "{what}. Riders see it beside your name.": "{what}। राइडर इसे आपके नाम के पास देखते हैं।",
  "Keep Current": "मौजूदा रखें",
  "Saved, but your current share didn’t switch over. Open Ride Mode to restart sharing with the new setting.": "सेव हो गया, लेकिन आपकी मौजूदा शेयरिंग नहीं बदली। नई सेटिंग से शेयरिंग फिर शुरू करने के लिए राइड मोड खोलें।",
  "How often this device tells your group where you are while you share your location. Fewer updates use less battery.": "लोकेशन शेयर करते समय यह डिवाइस आपके ग्रुप को कितनी बार बताता है कि आप कहां हैं। कम अपडेट में कम बैटरी लगती है।",
  "Your Group Sees You Less Often": "आपका ग्रुप आपको कम बार देखेगा",
  "Your dot can trail up to {heartbeatSec} seconds behind you, so you’re harder to follow and to find if you stop.": "आपका बिंदु आपसे {heartbeatSec} सेकंड तक पीछे रह सकता है, इसलिए आपको फ़ॉलो करना और रुकने पर ढूंढना मुश्किल होगा।",
  "Switch Back to Best Accuracy": "सबसे सटीक पर वापस जाएं",
  "This setting is for this device only. Need Help, EMERGENCY and your other taps still send right away on every setting. Other riders aren’t told which one you picked.": "यह सेटिंग सिर्फ़ इस डिवाइस के लिए है। मदद चाहिए, इमरजेंसी और आपके बाकी टैप हर सेटिंग पर तुरंत भेजे जाते हैं। दूसरे राइडर को नहीं बताया जाता कि आपने कौन सी चुनी।",
  "Recommended": "सुझाया गया",
  "You don’t see their messages in ride chat or group chat, or get chat notifications from them. They aren’t told. Need Help and EMERGENCY alerts from a ride you’re on always come through.": "आपको राइड चैट या ग्रुप चैट में उनके संदेश नहीं दिखते, और उनसे चैट नोटिफ़िकेशन नहीं आते। उन्हें नहीं बताया जाता। आपकी राइड से मदद चाहिए और इमरजेंसी अलर्ट हमेशा आते हैं।",
  "Loading…": "लोड हो रहा है…",
