  "In Map Mode, tap Record and ride, or Draw to map a custom trail. Your trails are private until you share them, and they show on every device you sign in on. A rider trail you save shows here too.": "मैप मोड में रिकॉर्ड टैप करके राइड करें, या अपनी ट्रेल मैप करने के लिए बनाएं टैप करें। आपकी ट्रेल शेयर करने तक प्राइवेट रहती हैं, और जिस भी डिवाइस पर आप साइन इन करें वहां दिखती हैं। आपकी सेव की हुई राइडर ट्रेल भी यहां दिखती है।",
  "Notifications Come to the iPhone App": "नोटिफ़िकेशन iPhone ऐप में आते हैं",
  "Your choices here apply on your phone too.": "यहां आपकी पसंद आपके फ़ोन पर भी लागू होती है।",
  "Notifications Are Off for OnMyLead": "OnMyLead के लिए नोटिफ़िकेशन बंद हैं",
  "Your phone is blocking them, so nothing below can reach you. Turn on Allow Notifications for OnMyLead.": "आपका फ़ोन इन्हें रोक रहा है, इसलिए नीचे का कुछ भी आप तक नहीं पहुंच सकता। OnMyLead के लिए नोटिफ़िकेशन की अनुमति चालू करें।",
  "Let OnMyLead Send Notifications": "OnMyLead को नोटिफ़िकेशन भेजने दें",
  "Turn On Notifications": "नोटिफ़िकेशन चालू करें",
  "So you hear when someone in your group needs help, even with the phone in your pocket.": "ताकि ग्रुप में किसी को मदद चाहिए तो आपको पता चले, फ़ोन जेब में होने पर भी।",
  "These settings start working with the next server update. Until then, ride chat still pops up while the app is open.": "ये सेटिंग अगले सर्वर अपडेट से काम करना शुरू करेंगी। तब तक ऐप खुला रहने पर राइड चैट दिखती रहेगी।",
  "Help and EMERGENCY alerts are always on, even in quiet hours.": "मदद और इमरजेंसी अलर्ट हमेशा चालू रहते हैं, शांत घंटों में भी।",
  "SOS": "SOS",
  "Help and EMERGENCY": "मदद और इमरजेंसी",
  "When someone in your group taps Need help or EMERGENCY. Always on, even in quiet hours.": "जब आपके ग्रुप में कोई मदद चाहिए या इमरजेंसी टैप करे। हमेशा चालू, शांत घंटों में भी।",
  "Email When a Ride Is Cancelled": "राइड रद्द होने पर ईमेल",
  "An email if a ride you joined is cancelled or removed, as well as the notification.": "आपकी शामिल हुई राइड रद्द होने या हटने पर नोटिफ़िकेशन के साथ ईमेल भी।",
  "Email Me Too": "मुझे ईमेल भी करें",
  "The same Pro Trial reminders by email.": "Pro ट्रायल की वही याद दिलाने वाली सूचनाएं ईमेल से।",
  "Show Message Text": "संदेश का टेक्स्ट दिखाएं",
  "Off keeps messages off your lock screen. You’ll see who wrote, not what.": "बंद रखने पर संदेश आपकी लॉक स्क्रीन पर नहीं दिखते। आपको दिखेगा किसने लिखा, क्या लिखा नहीं।",
  "Ride reminder": "राइड रिमाइंडर",
  "A heads-up before each ride you’ve joined, with the meeting spot.": "आपकी शामिल हुई हर राइड से पहले मिलने की जगह के साथ सूचना।",
