  "At {spot}": "{spot} पर",
  "Turn Off": "बंद करें",
  "Switch on Out Riding to see who else is out near you, like friends showing online in a game. Off until you switch it on.": "आसपास और कौन राइड पर है, देखने के लिए राइड पर चालू करें, जैसे गेम में दोस्त ऑनलाइन दिखते हैं। जब तक आप चालू न करें, बंद रहता है।",
  "Who Can See Me": "मुझे कौन देख सकता है",
