  "Shown to riders who can see you. Leave it blank to just show the distance.": "जो राइडर आपको देख सकते हैं उन्हें दिखता है। सिर्फ़ दूरी दिखाने के लिए खाली छोड़ें।",
  "Windrock Park": "Windrock Park",
  "Riders see your name and roughly how far away you are, never where you are. It turns off on its own at the end you pick, or after {IDLE_HOURS} hours without opening OnMyLead.{v}": "राइडर आपका नाम और लगभग कितनी दूर हैं, देखते हैं, आप कहां हैं यह कभी नहीं। यह आपके चुने समय पर, या OnMyLead खोले बिना {IDLE_HOURS} घंटे बाद अपने आप बंद हो जाता है।{v}",
  "Your browser will ask for your location.": "आपका ब्राउज़र आपकी लोकेशन मांगेगा।",
