  "Within": "इसके भीतर",
  "{r} Mi": "{r} mi",
  "Switch on Out Riding to see who’s out near you. You only see others while they can see you.": "आसपास कौन राइड पर है, देखने के लिए राइड पर चालू करें। आप दूसरों को तभी देखते हैं जब वे आपको देख सकें।",
  "Lead as many rides as you like, ride with no signal and keep every ride you’ve been on.": "जितनी चाहें उतनी राइड लीड करें, बिना सिग्नल के राइड करें और अपनी हर राइड सहेज कर रखें।",
  "Manage Subscription": "सब्सक्रिप्शन मैनेज करें",
