  "Draw the trail on the map or import a GPX file. Riders see it in Ride Mode with everyone placed along it.": "मैप पर ट्रेल बनाएं या GPX फ़ाइल इम्पोर्ट करें। राइडर इसे राइड मोड में देखते हैं, सबकी जगह उस पर दिखती है।",
