  "Chat": "चैट",
  "Pick who you want to report for harassment, threats or anything else that breaks the rider rules. It goes to the OnMyLead team. They aren’t told who reported them. If anyone is in danger, call 911.": "उत्पीड़न, धमकी या राइडर नियम तोड़ने वाली किसी बात के लिए जिसकी रिपोर्ट करनी है उसे चुनें। यह OnMyLead टीम के पास जाती है। उन्हें नहीं बताया जाता कि रिपोर्ट किसने की। अगर कोई ख़तरे में है, तो 911 पर कॉल करें।",
  "Search": "खोजें",
  "Rider name": "राइडर का नाम",
