  "Emergency": "इमरजेंसी",
  "This alerts everyone on the ride with your location. It does not contact emergency services. Call 911 if anyone is hurt.": "यह राइड पर सबको आपकी लोकेशन के साथ अलर्ट भेजता है। यह इमरजेंसी सेवाओं से संपर्क नहीं करता। कोई घायल हो तो 911 पर कॉल करें।",
  "Alert My Group": "मेरे ग्रुप को अलर्ट करें",
  "Alert my group: send EMERGENCY to everyone on this ride": "मेरे ग्रुप को अलर्ट करें: इस राइड पर सबको इमरजेंसी भेजें",
  "Call 911": "911 पर कॉल करें",
  "Clear the route?": "रूट साफ़ करें?",
  "This removes every point. Nothing is saved until you tap Save Route.": "इससे हर पॉइंट हट जाएगा। जब तक आप रूट सेव करें टैप नहीं करते, कुछ सेव नहीं होता।",
  "mi": "mi",
  "Import GPX": "GPX इम्पोर्ट करें",
  "Use One of My Trails": "मेरी कोई ट्रेल इस्तेमाल करें",
  "Only riders on this ride can see the route.{v}": "सिर्फ़ इस राइड के राइडर रूट देख सकते हैं।{v}",
  "It’s in the OnMyLead app as soon as you save.": "सेव करते ही यह OnMyLead ऐप में आ जाता है।",
  "Trails: {OSM_ATTRIBUTION}": "ट्रेल: {OSM_ATTRIBUTION}",
  "How the route joins your points": "रूट आपके पॉइंट कैसे जोड़ता है",
  "Saved on This Phone": "इस फ़ोन पर सेव",
  "Add at My Location": "मेरी लोकेशन पर जोड़ें",
  "Waypoints are never public. Shared ones and planned stops show only to riders on this ride.": "वेपॉइंट कभी सार्वजनिक नहीं होते। शेयर किए गए वेपॉइंट और प्लान किए स्टॉप सिर्फ़ इस राइड के राइडर को दिखते हैं।",
  "Pick Public or Private at the top.": "ऊपर सार्वजनिक या प्राइवेट चुनें।",
  "Give the ride a name.": "राइड को नाम दें।",
  "Pick a meeting time.": "मिलने का समय चुनें।",
  "Pick a day from today up to three years out.": "आज से तीन साल तक का कोई दिन चुनें।",
  "Set the meeting point: search a place, use your location or paste coordinates like \"38.57, -109.55\".": "मिलने की जगह सेट करें: कोई जगह खोजें, अपनी लोकेशन इस्तेमाल करें या \"38.57, -109.55\" जैसे कोऑर्डिनेट पेस्ट करें।",
  "Pick Mapped or Freeride under The Route.": "रूट के नीचे मैप्ड या फ़्रीराइड चुनें।",
  "Plan it here on the big screen. The ride, its route and its stops show up in the OnMyLead app on your iPhone as soon as you save.": "इसे यहां बड़ी स्क्रीन पर प्लान करें। सेव करते ही राइड, उसका रूट और स्टॉप आपके iPhone के OnMyLead ऐप में दिखने लगते हैं।",
