  "Riding {fromTrail}": "{fromTrail} राइड करें",
  "The trail is the route, and its start is the meeting point. Change anything, pick the day and create it.": "ट्रेल ही रूट है, और उसकी शुरुआत मिलने की जगह है। कुछ भी बदलें, दिन चुनें और बनाएं।",
  "{v} Width Limit": "{v} चौड़ाई सीमा",
  "For Your Event": "आपके इवेंट के लिए",
  "Once it’s created, this ride shows under the event’s Group Rides.": "बनने के बाद यह राइड इवेंट की ग्रुप राइड में दिखेगी।",
  "Unlimited With Pro": "Pro के साथ असीमित",
  "What Kind of Ride?": "कैसी राइड?",
