  "Invite Code": "इनवाइट कोड",
  "Riders open the ride with its link, QR code or this code. Leave it empty and OnMyLead makes one, or type your own so it’s easy to say out loud.{v}": "राइडर इसके लिंक, QR कोड या इस कोड से राइड खोलते हैं। खाली छोड़ें तो OnMyLead एक बना देगा, या अपना कोड लिखें ताकि बोलकर बताना आसान हो।{v}",
  "Anyone with the code can join, so pick one that’s hard to guess.": "कोड वाला कोई भी शामिल हो सकता है, इसलिए ऐसा कोड चुनें जिसका अंदाज़ा लगाना मुश्किल हो।",
