  "Invite a Group": "ग्रुप को बुलाएं",
  "Everyone in the groups you pick gets a notification and sees the ride on their home screen. They join with one tap.": "आपके चुने ग्रुप के सभी लोगों को नोटिफ़िकेशन मिलता है और वे होम स्क्रीन पर राइड देखते हैं। वे एक टैप में शामिल होते हैं।",
