  "General": "सामान्य",
  "My Plan": "मेरा प्लान",
  "Starlink doesn’t share plan or usage details with other apps, so jot them down here. Check usage in the Starlink app.": "Starlink प्लान या इस्तेमाल की जानकारी दूसरे ऐप के साथ शेयर नहीं करता, इसलिए उन्हें यहां लिख लें। इस्तेमाल Starlink ऐप में देखें।",
