  "Estimates. Assumes 90% conversion efficiency and 75% of panel rating. Snow melt, heat and heavy use draw more.": "अनुमान। 90% कन्वर्ज़न दक्षता और पैनल रेटिंग का 75% मानकर। बर्फ़ पिघलाना, गर्मी और ज़्यादा इस्तेमाल ज़्यादा बिजली खींचते हैं।",
  "Sign In to Save Your Plan and Power Setup": "अपना प्लान और पावर सेटअप सेव करने के लिए साइन इन करें",
  "OnMyLead Pro starts with the next server update. Until then every feature stays open to you.": "OnMyLead Pro अगले सर्वर अपडेट से शुरू होगा। तब तक हर फ़ीचर आपके लिए खुला है।",
  "See What Pro Includes": "Pro में क्या है देखें",
  "Live tracking, SOS, Ride Bubble, Mechanical Issue alerts, family links and joining rides are free on every plan.": "लाइव ट्रैकिंग, SOS, राइड बबल, मैकेनिकल समस्या अलर्ट, फ़ैमिली लिंक और राइड में शामिल होना हर प्लान पर मुफ़्त है।",
  "Joining a Ride": "राइड में शामिल होना",
  "Location and Battery": "लोकेशन और बैटरी",
  "Pro and Your Subscription": "Pro और आपका सब्सक्रिप्शन",
  "Reporting and Blocking": "रिपोर्ट और ब्लॉक",
  "Deleting Your Account": "अपना अकाउंट हटाना",
  "In an Emergency": "इमरजेंसी में",
  "Tilt Is in the App": "झुकाव ऐप में है",
  "The roll and pitch meter and Crash Alert read the motion sensors in your phone or tablet, so they’re in the OnMyLead app for iPhone, iPad and Android, not on the website.": "रोल और पिच मीटर और क्रैश अलर्ट आपके फ़ोन या टैबलेट के मोशन सेंसर पढ़ते हैं, इसलिए ये iPhone, iPad और Android के OnMyLead ऐप में हैं, वेबसाइट पर नहीं।",
  "No Reading Yet": "अभी कोई रीडिंग नहीं",
  "The motion sensors haven’t sent a reading yet. Hold still for a second and try again.": "मोशन सेंसर ने अभी रीडिंग नहीं भेजी। एक सेकंड स्थिर रखें और फिर कोशिश करें।",
  "No Motion Sensors Found": "कोई मोशन सेंसर नहीं मिला",
  "This device doesn’t report tilt, so the meter can’t show a reading.": "यह डिवाइस झुकाव नहीं बताता, इसलिए मीटर रीडिंग नहीं दिखा सकता।",
  "Sets level for how the phone sits in its mount": "फ़ोन माउंट में जैसे रखा है उसे लेवल मानता है",
  "Reset Max": "अधिकतम रीसेट करें",
  "Clear Zero": "ज़ीरो हटाएं",
  "Tilt Warnings": "झुकाव चेतावनी",
  "Warn Me": "मुझे चेतावनी दें",
  "Buzzes when you lean past your limit.": "आपकी सीमा से ज़्यादा झुकने पर वाइब्रेट करता है।",
  "Roll Limit": "रोल सीमा",
  "Pitch Limit": "पिच सीमा",
  "Say It Out Loud": "बोलकर बताएं",
  "Speaks the angle, like “Roll 28 left”.": "कोण बोलता है, जैसे “रोल 28 बाएं”।",
  "Show in Map Mode and Ride Mode": "मैप मोड और राइड मोड में दिखाएं",
  "The Tilt tile over the map.": "मैप के ऊपर झुकाव टाइल।",
  "Every vehicle tips at a different angle. These are reminders, not a promise you won’t roll. On a motorcycle, turn Warn Me off: leaning into turns is normal.": "हर गाड़ी अलग कोण पर पलटती है। ये याद दिलाने के लिए हैं, यह वादा नहीं कि आप नहीं पलटेंगे। मोटरसाइकिल पर मुझे चेतावनी दें बंद रखें: मोड़ पर झुकना सामान्य है।",
  "Crash Alert": "क्रैश अलर्ट",
  "In Ride Mode, a hard hit or a rollover followed by a stop starts a 30 second countdown. If you don’t tap I’m OK, your group gets an EMERGENCY alert with your location. A dropped phone doesn’t set it off.": "राइड मोड में ज़ोरदार टक्कर या पलटने के बाद रुकने पर 30 सेकंड की उलटी गिनती शुरू होती है। अगर आप मैं ठीक हूं टैप नहीं करते, तो आपके ग्रुप को आपकी लोकेशन के साथ इमरजेंसी अलर्ट मिलता है। फ़ोन गिरने से यह चालू नहीं होता।",
  "Sensitivity": "संवेदनशीलता",
  "Crash Alert tells your group only. It doesn’t call 911 or emergency services. It works while Ride Mode is open, and with no signal the alert sends as soon as your phone reconnects.": "क्रैश अलर्ट सिर्फ़ आपके ग्रुप को बताता है। यह 911 या इमरजेंसी सेवाओं को कॉल नहीं करता। यह राइड मोड खुला रहने पर काम करता है, और सिग्नल न होने पर फ़ोन दोबारा जुड़ते ही अलर्ट भेजा जाता है।",
  "Crash Alert {v}": "क्रैश अलर्ट {v}",
  "That trip is not in your list.": "वह ट्रिप आपकी सूची में नहीं है।",
  "All Trips": "सभी ट्रिप",
  "Uncheck everything?": "सबका निशान हटाएं?",
  "Every item goes back to not packed. The list stays.": "हर आइटम फिर से पैक नहीं हुआ बन जाएगा। सूची बनी रहेगी।",
  "Uncheck All": "सबका निशान हटाएं",
  "Delete this trip?": "यह ट्रिप हटाएं?",
  "For the ride: {name}": "राइड के लिए: {name}",
  "Start From a Packing List": "पैकिंग सूची से शुरू करें",
  "Day ride, overnight and more, in one tap": "दिन की राइड, रात भर और बहुत कुछ, एक टैप में",
  "Add a Starter List": "शुरुआती सूची जोड़ें",
  "One tap adds the items. Add as many as fit the trip; nothing is added twice.": "एक टैप से आइटम जुड़ जाते हैं। ट्रिप के हिसाब से जितनी चाहें जोड़ें; कुछ भी दो बार नहीं जुड़ता।",
  "Add an Item": "आइटम जोड़ें",
  "{packed} of {total}": "{total} में से {packed}",
  "After the Trip": "ट्रिप के बाद",
