  "Your dot updates about every 15 seconds or 25 m (80 ft). Best for following the leader and finding someone who stopped.": "आपका बिंदु लगभग हर 15 सेकंड या 25 m (80 ft) पर अपडेट होता है। लीडर को फ़ॉलो करने और रुके हुए को ढूंढने के लिए सबसे अच्छा।",
  "Your dot updates about every 30 seconds or 75 m (250 ft). Uses noticeably less battery on long days.": "आपका बिंदु लगभग हर 30 सेकंड या 75 m (250 ft) पर अपडेट होता है। लंबे दिनों में काफ़ी कम बैटरी लगती है।",
  "Your dot updates about every 45 seconds or 200 m (650 ft) and can be off by up to about 100 m (330 ft). For multi-day trips with no way to charge.": "आपका बिंदु लगभग हर 45 सेकंड या 200 m (650 ft) पर अपडेट होता है और लगभग 100 m (330 ft) तक गलत हो सकता है। कई दिन की ट्रिप के लिए जहां चार्ज करने का कोई तरीका नहीं।",
