  "Just Now": "अभी-अभी",
  "{totalMin} Min Ago": "{totalMin} मिनट पहले",
  "{totalHr} Hr Ago": "{totalHr} घंटे पहले",
  "{totalHr} Hr {m} Min Ago": "{totalHr} घंटे {m} मिनट पहले",
  "Requested": "रिक्वेस्ट भेजी",
  "Accept Friend Request": "फ़्रेंड रिक्वेस्ट स्वीकार करें",
  "Add riders you know as friends": "जिन राइडर को आप जानते हैं उन्हें दोस्त बनाएं",
  "You and {name} are friends now.": "अब आप और {name} दोस्त हैं।",
  "You’ve already asked {name}.": "आप पहले ही {name} से पूछ चुके हैं।",
  "Friend request sent to {name}.": "{name} को फ़्रेंड रिक्वेस्ट भेजी गई।",
  "No signal. Check your connection and try again.": "सिग्नल नहीं। अपना कनेक्शन जांचें और फिर कोशिश करें।",
  "You blocked this rider. Unblock them from You, Blocked Riders to add them.": "आपने इस राइडर को ब्लॉक किया है। जोड़ने के लिए आप > ब्लॉक किए गए राइडर से अनब्लॉक करें।",
  "You already asked this rider this week.": "आप इस हफ़्ते पहले ही इस राइडर से पूछ चुके हैं।",
  "You’ve sent a lot of friend requests today. Try again tomorrow.": "आपने आज बहुत सारी फ़्रेंड रिक्वेस्ट भेजी हैं। कल फिर कोशिश करें।",
  "This friend link doesn’t work anymore. Ask for a new one.": "यह फ़्रेंड लिंक अब काम नहीं करता। नया मांगें।",
  "This request isn’t there anymore.": "यह रिक्वेस्ट अब नहीं है।",
  "That’s your own friend link.": "यह आपका अपना फ़्रेंड लिंक है।",
  "You can add riders you’ve ridden with or see Out Riding. For anyone else, share your friend link.": "आप उन राइडर को जोड़ सकते हैं जिनके साथ आपने राइड की है या जिन्हें राइड पर में देखा है। बाकी किसी के लिए अपना फ़्रेंड लिंक शेयर करें।",
