  "Invited {count} {v} from {groupName}. They get a notification and see the ride on their home screen.": "{groupName} से {count} {v} को बुलाया। उन्हें नोटिफ़िकेशन मिलता है और वे होम स्क्रीन पर राइड देखते हैं।",
