  "You’re taken off the waitlist for {rideName}. You can join again later with the ride’s link or code.": "आपको {rideName} की वेटलिस्ट से हटा दिया जाएगा। आप बाद में राइड के लिंक या कोड से फिर शामिल हो सकते हैं।",
  "The organizer won’t see your request to join {rideName} anymore. You can ask again later with the ride’s link or code.": "आयोजक को अब {rideName} में शामिल होने की आपकी रिक्वेस्ट नहीं दिखेगी। आप बाद में राइड के लिंक या कोड से फिर पूछ सकते हैं।",
  "Give {rideName} to {name}?": "{rideName} {name} को सौंपें?",
  "{name} becomes the organizer and leader, and you leave the ride. Your location sharing for this ride stops. You can rejoin later as a rider with the ride’s link or code.": "{name} आयोजक और लीडर बनेंगे, और आप राइड छोड़ देंगे। इस राइड के लिए आपकी लोकेशन शेयरिंग रुक जाएगी। आप बाद में राइड के लिंक या कोड से राइडर के रूप में फिर शामिल हो सकते हैं।",
  "{why}{others} on this ride will get a notification and an email saying it’s cancelled. This can’t be undone.": "{why}इस राइड के {others} को नोटिफ़िकेशन और ईमेल मिलेगा कि यह रद्द हो गई है। इसे वापस नहीं लिया जा सकता।",
  "{why}It stays in your list as Cancelled. This can’t be undone.": "{why}यह आपकी सूची में रद्द के रूप में रहेगी। इसे वापस नहीं लिया जा सकता।",
  "That rider has left the ride. Pick someone else.": "वह राइडर राइड छोड़ चुका है। किसी और को चुनें।",
