  "Apple lets OnMyLead change the volume of music from other apps, like Spotify, but not skip songs. Use your headset or helmet buttons to skip.": "Apple, OnMyLead को Spotify जैसे दूसरे ऐप के म्यूज़िक का वॉल्यूम बदलने देता है, लेकिन गाने आगे बढ़ाने नहीं देता। आगे बढ़ाने के लिए अपने हेडसेट या हेलमेट के बटन इस्तेमाल करें।",
  "Nothing is playing. Play starts Apple Music.": "कुछ नहीं चल रहा। चलाएं दबाने पर Apple Music शुरू होता है।",
  "Nothing is playing. Play resumes the app you last listened to.": "कुछ नहीं चल रहा। चलाएं दबाने पर वह ऐप फिर चलता है जो आपने आखिरी बार सुना था।",
  "Music Controls. Playing {what}": "म्यूज़िक कंट्रोल। {what} चल रहा है",
