  "A rider messages you, say after seeing you Out Riding. Mute one conversation from inside it.": "कोई राइडर आपको संदेश भेजता है, जैसे आपको राइड पर देखने के बाद। किसी एक बातचीत को उसके अंदर से म्यूट करें।",
  "A rider asks to be your friend, or accepts your request.": "कोई राइडर आपका दोस्त बनना चाहता है, या आपकी रिक्वेस्ट स्वीकार करता है।",
  "Likes and Comments": "लाइक और कमेंट",
  "A rider likes or comments on your post, ride, badge or trail, or replies after you comment.": "कोई राइडर आपकी पोस्ट, राइड, बैज या ट्रेल को लाइक करता है या उस पर कमेंट करता है, या आपके कमेंट के बाद जवाब देता है।",
  "Badges and Pro Trial": "बैज और Pro ट्रायल",
  "When you earn a badge, when a trail you shared is hidden, and a week, 3 days and a day before your Pro Trial ends.": "जब आप बैज पाते हैं, जब आपकी शेयर की ट्रेल छिपाई जाती है, और आपका Pro ट्रायल खत्म होने से एक हफ़्ता, 3 दिन और एक दिन पहले।",
