  "This Weekend": "इस वीकेंड",
  "Only your friends, and riders you’ve been on a ride with or share a riding group with, can see you.": "सिर्फ़ आपके दोस्त, और वे राइडर जिनके साथ आप राइड पर गए हैं या जो आपके राइडिंग ग्रुप में हैं, आपको देख सकते हैं।",
  "Any OnMyLead rider who is Out Riding nearby and also picked Everyone Nearby. Handy at a park for the weekend.": "कोई भी OnMyLead राइडर जो आसपास राइड पर है और जिसने भी आसपास के सभी चुना है। वीकेंड पर किसी पार्क में काम का।",
