  "Your area was updated a lot this hour. It’ll update again soon.": "इस घंटे आपका इलाका बहुत बार अपडेट हुआ। यह जल्द फिर अपडेट होगा।",
  "OnMyLead needs your location to show who’s out near you.": "आपके आसपास कौन राइड पर है, दिखाने के लिए OnMyLead को आपकी लोकेशन चाहिए।",
  "You’ve hit today’s message limit. Try again tomorrow.": "आप आज की संदेश सीमा तक पहुंच गए हैं। कल फिर कोशिश करें।",
