  "Reward Applied": "इनाम लागू हुआ",
  "Your next Google Play bill was pushed back 6 months. Thanks for spreading the word.": "आपका अगला Google Play बिल 6 महीने आगे खिसका दिया गया। बात फैलाने के लिए धन्यवाद।",
  "Reward Used": "इनाम इस्तेमाल हुआ",
  "You’re on Pro Annual at half price for your first year. Thanks for spreading the word.": "आप अपने पहले साल के लिए आधी कीमत पर Pro सालाना पर हैं। बात फैलाने के लिए धन्यवाद।",
  "Your 50% Off Code": "आपका 50% छूट कोड",
  "Code {code}. Redeem it in the App Store before it expires.": "कोड {code}। समय सीमा खत्म होने से पहले इसे App Store में रिडीम करें।",
  "You Earned 6 Months": "आपने 6 महीने कमाए",
  "{thanks} You already pay for Pro on Google Play, so your next bill moves back 6 months instead.": "{thanks} आप पहले से Google Play पर Pro के लिए भुगतान करते हैं, इसलिए इसके बजाय आपका अगला बिल 6 महीने आगे खिसकता है।",
  "You Earned 50% Off Pro Annual": "आपने Pro सालाना पर 50% छूट कमाई",
  "Claim by {v}.": "{v} तक लें।",
  "We’re out of discount codes for a moment. Try again tomorrow; your reward is saved.": "अभी हमारे पास छूट कोड खत्म हो गए हैं। कल फिर कोशिश करें; आपका इनाम सेव है।",
  "This discount has expired.": "इस छूट की समय सीमा खत्म हो गई है।",
  "You’ve already used this discount.": "आप यह छूट पहले ही इस्तेमाल कर चुके हैं।",
