  "Give the ride to {name}?": "राइड {name} को दें?",
  "{name} becomes the organizer and leader. You stay on the ride as a rider and can't undo this yourself.": "{name} आयोजक और लीडर बनेंगे। आप राइडर के रूप में राइड पर रहेंगे और इसे खुद वापस नहीं कर सकते।",
  "Hand the lead to {name}?": "लीड {name} को सौंपें?",
  "{name} leads from here, and messages to the leader go to them. You stay on the ride as a rider.": "{name} यहां से लीड करेंगे, और लीडर को भेजे संदेश उन्हें जाएंगे। आप राइडर के रूप में राइड पर रहेंगे।",
  "Handing off the ride and picking a tail gunner aren’t switched on yet.": "राइड सौंपना और टेल गनर चुनना अभी चालू नहीं है।",
