  "Earn your first badge level to get on the board.": "बोर्ड पर आने के लिए अपना पहला बैज लेवल पाएं।",
  "Everywhere": "हर जगह",
  "Leaderboard. See where you rank in your state, your country and everywhere": "लीडरबोर्ड। देखें आपके राज्य, देश और हर जगह आपकी रैंक क्या है",
  "No country matches “{v}”.": "“{v}” से मेल खाता कोई देश नहीं।",
  "No tilt tile, readings or tilt warnings. Crash Alert still works.": "न झुकाव टाइल, न रीडिंग, न झुकाव चेतावनी। क्रैश अलर्ट फिर भी काम करता है।",
  "Pick the state or country you ride from to be on its leaderboard. Riders see it beside your name there, and nowhere else. It’s optional, and it never shares where you are.": "जिस राज्य या देश से आप राइड करते हैं उसे चुनें ताकि आप उसके लीडरबोर्ड पर आएं। राइडर इसे वहीं आपके नाम के पास देखते हैं, और कहीं नहीं। यह वैकल्पिक है, और यह कभी नहीं बताता कि आप कहां हैं।",
  "Pick where you ride from to be on country and state boards.": "देश और राज्य बोर्ड पर आने के लिए चुनें कि आप कहां से राइड करते हैं।",
  "Place your phone where it will be mounted, with the vehicle on flat and level ground, then press {button} to calibrate it.": "गाड़ी को समतल ज़मीन पर रखें, फ़ोन वहां रखें जहां वह माउंट होगा, फिर कैलिब्रेट करने के लिए {button} दबाएं।",
  "Remove My Area": "मेरा इलाका हटाएं",
  "Riders are ranked by the badge levels they earned by riding, the same count as their rank. Ties go to more Gold, then more Silver, then whoever got there first. Brand Ambassador and OnMyLead Founder don’t count. Only your name, picture, badges and the state or country you picked show here, never where you are.": "राइडर को राइड करके कमाए बैज लेवल से रैंक किया जाता है, वही गिनती जो उनकी रैंक है। बराबरी पर ज़्यादा गोल्ड वाला आगे, फिर ज़्यादा सिल्वर वाला, फिर जो पहले पहुंचा। Brand Ambassador और OnMyLead Founder नहीं गिने जाते। यहां सिर्फ़ आपका नाम, तस्वीर, बैज और आपका चुना राज्य या देश दिखता है, आप कहां हैं यह कभी नहीं।",
  "Roll and pitch on this screen and in Map Mode and Ride Mode.": "इस स्क्रीन पर और मैप मोड और राइड मोड में रोल और पिच।",
