  "No Service. Sharing With {n} Nearby Phone Over Bluetooth (Your Spot Stays Private Until You Share).": "सर्विस नहीं। ब्लूटूथ से पास के {n} फ़ोन के साथ शेयर हो रहा है (आपके शेयर करने तक आपकी जगह प्राइवेट रहती है)।",
  "No Service. Sharing With {n} Nearby Phones Over Bluetooth (Your Spot Stays Private Until You Share).": "सर्विस नहीं। ब्लूटूथ से पास के {n} फ़ोन के साथ शेयर हो रहा है (आपके शेयर करने तक आपकी जगह प्राइवेट रहती है)।",
