  "Unblock {name}": "{name} को अनब्लॉक करें",
  "Your browser and a short log of what the page just did go with your message, to help us fix it. Never your location or anything you typed.": "आपके मैसेज के साथ आपका ब्राउज़र और पेज ने अभी जो किया उसका छोटा लॉग जाता है, ताकि हम ठीक कर सकें। कभी भी आपकी लोकेशन या टाइप की गई कोई चीज़ नहीं।",
  "Your phone model, app version and a short log of what the app just did go with your message, to help us fix it. Never your location or anything you typed.": "आपके मैसेज के साथ फ़ोन मॉडल, ऐप वर्ज़न और ऐप ने अभी जो किया उसका छोटा लॉग जाता है, ताकि हम ठीक कर सकें। कभी भी आपकी लोकेशन या टाइप की गई कोई चीज़ नहीं।",
  "We couldn’t find that event.": "वह इवेंट नहीं मिला।",
  "{title}, {v} at {location_name}. Agenda, group rides and who’s going: {link}": "{title}, {v}, {location_name}। एजेंडा, ग्रुप राइड और कौन आ रहा है: {link}",
  "An event can have up to {v} photos. Remove one to add another.": "एक इवेंट में ज़्यादा से ज़्यादा {v} फ़ोटो हो सकती हैं। दूसरी जोड़ने के लिए एक हटाएँ।",
  "Couldn’t add the photos.": "फ़ोटो नहीं जोड़ी जा सकीं।",
  "{name} is invited to {v}. They manage it as a Co-Organizer once they join.": "{name} को {v} में बुलाया गया है। जुड़ते ही वे सह-आयोजक के तौर पर इसे संभालेंगे।",
  "Couldn’t delete the event.": "इवेंट डिलीट नहीं हो सका।",
