  "Photo {v}. Change": "फ़ोटो {v}। बदलें",
  "Photo {v}": "फ़ोटो {v}",
  "{name} stays on as a ride; it just isn’t part of {title} any more.": "{name} राइड के तौर पर बनी रहेगी; बस अब {title} का हिस्सा नहीं रहेगी।",
  "Going ({v})": "आ रहे हैं ({v})",
