  "Add Photos": "फ़ोटो जोड़ें",
  "Bring the Event Back": "इवेंट वापस लाएँ",
  "{title} | OnMyLead Events": "{title} | OnMyLead इवेंट",
  "{v} at {location_name}. Agenda, group rides and who’s going on OnMyLead.": "{v}, {location_name}। एजेंडा, ग्रुप राइड और कौन आ रहा है, OnMyLead पर।",
  "Pick a Ride Manager": "राइड मैनेजर चुनें",
  "Add a Co-Host": "को-होस्ट जोड़ें",
  "They become a Co-Organizer of {name}: they can approve riders, set roles and run the ride. If they aren’t on it yet, they get an invite first.": "वे {name} के सह-आयोजक बन जाते हैं: राइडर मंज़ूर कर सकते हैं, रोल तय कर सकते हैं और राइड चला सकते हैं। अगर वे अभी इसमें नहीं हैं, तो पहले उन्हें न्योता मिलता है।",
  "Pick from your friends and the riders you’ve ridden with.": "अपने दोस्तों और जिन राइडरों के साथ आप चले हैं, उनमें से चुनें।",
