  "Yours{v}": "आपके{v}",
  "Public events, soonest first.": "पब्लिक इवेंट, सबसे पहले आने वाले पहले।",
  "Public events everywhere. Allow location to see the ones near you first.": "हर जगह के पब्लिक इवेंट। आसपास वाले पहले देखने के लिए लोकेशन की अनुमति दें।",
  "Nothing Here Yet": "यहाँ अभी कुछ नहीं",
