  "Nothing within {v} miles yet. Widen the distance, or create one and it shows here for everyone.": "{v} मील के अंदर अभी कुछ नहीं। दूरी बढ़ाएँ, या एक बनाएँ और वह सबको यहाँ दिखेगा।",
