  ". Swipe Left to Clear": "। मिटाने के लिए बाएँ स्वाइप करें",
  "Notifications OnMyLead sends to your phone app show up here too, for 30 days.": "OnMyLead आपके फ़ोन पर जो नोटिफ़िकेशन भेजता है, वे भी यहाँ 30 दिन तक दिखते हैं।",
  "Ride messages, rider alerts, ride changes, invites and friend requests show up here for 30 days.": "राइड के मैसेज, राइडर अलर्ट, राइड में बदलाव, न्योते और दोस्ती की रिक्वेस्ट यहाँ 30 दिन तक दिखते हैं।",
  "New. ": "नया। ",
  "Clear {title}": "{title} मिटाएँ",
  "Send your link to a riding buddy who’s new to OnMyLead. When they finish their first ride, you both get Pro Annual for ${discounted} the first year instead of ${annual}.": "अपना लिंक ऐसे राइड साथी को भेजें जो OnMyLead पर नया है। जब वे अपनी पहली राइड पूरी करेंगे, तो आप दोनों को प्रो सालाना पहले साल ${annual} की जगह ${discounted} में मिलेगा।",
  "Invites aren’t open right now. Any discount you already earned is below.": "अभी न्योते खुले नहीं हैं। आपने जो छूट पहले कमाई है वह नीचे है।",
  "Copy Link": "लिंक कॉपी करें",
  "{name} invited you, and your first ride counted.": "{name} ने आपको बुलाया, और आपकी पहली राइड गिन ली गई।",
  "{name} invited you. Finish your first ride and you both get 50% off Pro Annual.": "{name} ने आपको बुलाया। अपनी पहली राइड पूरी करें और आप दोनों को प्रो सालाना पर 50% छूट मिलेगी।",
  "Your friend creates a new account with your link within {newAccountDays} days and finishes a ride that ran at least {minRideMinutes} minutes. Each rider can earn the discount once, and it can be claimed for 6 months. On iPhone and iPad it’s an App Store offer code; on Android it’s a Google Play offer. If you already pay for Pro on Google Play, your next bill moves back 6 months instead. The discount covers the first year of Pro Annual, which then renews at the regular price unless you cancel.": "आपका दोस्त {newAccountDays} दिनों के अंदर आपके लिंक से नया अकाउंट बनाता है और कम से कम {minRideMinutes} मिनट चली राइड पूरी करता है। हर राइडर छूट एक बार कमा सकता है, और इसे 6 महीने तक लिया जा सकता है। iPhone और iPad पर यह App Store ऑफ़र कोड है; Android पर Google Play ऑफ़र है। अगर आप पहले से Google Play पर प्रो के पैसे देते हैं, तो उसकी जगह आपका अगला बिल 6 महीने आगे खिसक जाता है। छूट प्रो सालाना के पहले साल पर लागू है, जो फिर सामान्य कीमत पर रिन्यू होता है जब तक आप रद्द न करें।",
  "Pick your {v} below.": "नीचे अपना {v} चुनें।",
  "That didn’t save. {message}": "वह सेव नहीं हुआ। {message}",
