  "No riders from {v} on the board yet. Riders show here once they pick where they ride from and earn a badge level.": "{v} से अभी कोई राइडर बोर्ड पर नहीं है। राइडर यहाँ तब दिखते हैं जब वे चुनते हैं कि कहाँ से राइड करते हैं और बैज लेवल कमाते हैं।",
