  "It’s removed from your Messages. {who} keeps their copy. If they message you again, it comes back.": "यह आपके मैसेज से हट जाता है। {who} के पास उनकी कॉपी रहती है। अगर वे फिर मैसेज करें, तो वापस आ जाता है।",
