  "It was taken off the public map. It’s still saved on this phone.": "इसे पब्लिक मैप से हटा दिया गया। यह अब भी इस फ़ोन पर सेव है।",
  "Riders rated its line inaccurate, so other riders can’t see it. It’s still saved on this phone. Re-record it and share again.": "राइडरों ने इसकी लाइन को गलत बताया, इसलिए दूसरे राइडर इसे नहीं देखते। यह अब भी इस फ़ोन पर सेव है। इसे दोबारा रिकॉर्ड करके फिर शेयर करें।",
  "Centers the map on you and follows you again": "मैप को आप पर सेंटर करता है और फिर से आपके पीछे चलता है",
  "Centers the map on you": "मैप को आप पर सेंटर करता है",
