  "Following a Rider Trail": "राइडर की ट्रेल फ़ॉलो कर रहे हैं",
  "Following": "फ़ॉलो कर रहे हैं",
  "Off Trail by {v}": "ट्रेल से {v} दूर",
  "To the Start": "शुरुआत तक",
  "Trip {tripV} {tripU}": "ट्रिप {tripV} {tripU}",
  "Tap any line to see what it is.": "यह क्या है जानने के लिए किसी भी लाइन पर टैप करें।",
  "Recording works in the OnMyLead app on your phone or tablet. Here you can measure, plan and look at trails.": "रिकॉर्डिंग आपके फ़ोन या टैबलेट के OnMyLead ऐप में काम करती है। यहाँ आप नाप सकते हैं, प्लान कर सकते हैं और ट्रेल देख सकते हैं।",
  "Turn on location for OnMyLead in Settings to record.": "रिकॉर्ड करने के लिए सेटिंग्स में OnMyLead के लिए लोकेशन चालू करें।",
  "Ride and OnMyLead draws your line. It stays on this phone unless you share it. Keep Map Mode open: the screen stays on while recording.": "राइड करें और OnMyLead आपकी लाइन खींचता है। जब तक आप शेयर न करें, यह इसी फ़ोन पर रहती है। मैप मोड खुला रखें: रिकॉर्डिंग के दौरान स्क्रीन चालू रहती है।",
  "Paused": "रुका हुआ",
  "Ledges, crossings, views": "चट्टानी सीढ़ियाँ, पानी के रास्ते, नज़ारे",
  "Along the Trails": "ट्रेल के साथ",
  "{v} the map where the spot is.": "मैप पर वहाँ {v} जहाँ वह जगह है।",
  "Finding the trail…": "ट्रेल ढूँढ रहे हैं…",
  "{v} the map where you want to measure from.": "मैप पर वहाँ {v} जहाँ से नापना है।",
  "Now {v} where you want to measure to.": "अब वहाँ {v} जहाँ तक नापना है।",
  "Add more points, mark spots, or save it as a custom trail.": "और पॉइंट जोड़ें, जगहें मार्क करें, या इसे कस्टम ट्रेल के तौर पर सेव करें।",
  "Cancel marking a spot": "जगह मार्क करना रद्द करें",
  "Mark a spot on the trail, like a ledge or water crossing": "ट्रेल पर कोई जगह मार्क करें, जैसे चट्टानी सीढ़ी या पानी का रास्ता",
  "Cancel Marking": "मार्क करना रद्द करें",
  "Mark a Spot": "जगह मार्क करें",
  "Couldn’t load the trail.": "ट्रेल लोड नहीं हो सकी।",
  "This trail isn’t on the public map any more.": "यह ट्रेल अब पब्लिक मैप पर नहीं है।",
  "It comes off the public map with its photos and ratings. Your copy stays in My Trails. Rides that used it keep their route.": "यह अपनी फ़ोटो और रेटिंग के साथ पब्लिक मैप से हट जाती है। आपकी कॉपी मेरी ट्रेल में रहती है। जिन राइड ने इसे इस्तेमाल किया, उनका रूट बना रहता है।",
  "It comes off the public map with its photos and ratings. Rides that used it keep their route.": "यह अपनी फ़ोटो और रेटिंग के साथ पब्लिक मैप से हट जाती है। जिन राइड ने इसे इस्तेमाल किया, उनका रूट बना रहता है।",
  "Couldn’t delete it.": "डिलीट नहीं हो सका।",
  "Couldn’t save it.": "सेव नहीं हो सका।",
  "Map of {name}": "{name} का मैप",
  "Photo of {name}": "{name} की फ़ोटो",
  "Change Your Rating": "अपनी रेटिंग बदलें",
  "Rate This Trail": "इस ट्रेल को रेट करें",
  "Saved to My Trails": "मेरी ट्रेल में सेव हो गया",
  "Save to My Trails": "मेरी ट्रेल में सेव करें",
  "That trail isn’t on this device.": "वह ट्रेल इस डिवाइस पर नहीं है।",
  "Couldn’t save.": "सेव नहीं हो सका।",
  "Every OnMyLead rider will see {v}, its named spots, photos and your ride name. Riders can rate it; if several say it’s inaccurate it’s hidden from them, but it stays on your phone.": "हर OnMyLead राइडर {v}, इसकी नाम वाली जगहें, फ़ोटो और आपकी राइड का नाम देखेगा। राइडर इसे रेट कर सकते हैं; अगर कई इसे गलत कहें तो यह उनसे छिप जाती है, पर आपके फ़ोन पर रहती है।",
  "Couldn’t share the trail.": "ट्रेल शेयर नहीं हो सकी।",
  "Couldn’t stop sharing.": "शेयर करना बंद नहीं हो सका।",
  "A trail can have up to {v} photos.": "एक ट्रेल में ज़्यादा से ज़्यादा {v} फ़ोटो हो सकती हैं।",
  "Couldn’t add that photo.": "वह फ़ोटो नहीं जोड़ी जा सकी।",
  "It’s deleted from this phone and taken off the public map.": "यह इस फ़ोन से डिलीट हो जाती है और पब्लिक मैप से हट जाती है।",
  "It’s deleted from this phone.": "यह इस फ़ोन से डिलीट हो जाती है।",
  "Couldn’t take it off the public map, so it wasn’t deleted. {message}": "पब्लिक मैप से नहीं हटा सके, इसलिए डिलीट नहीं हुई। {message}",
  "Couldn’t delete.": "डिलीट नहीं हो सका।",
  "OnMyLead took this trail off the public map. It’s still yours here.": "OnMyLead ने यह ट्रेल पब्लिक मैप से हटा दी। यहाँ यह अब भी आपकी है।",
  "Several riders rated this line inaccurate, so other riders can’t see it. It’s still yours here. Record it again and share the new one.": "कई राइडरों ने इस लाइन को गलत बताया, इसलिए दूसरे राइडर इसे नहीं देखते। यहाँ यह अब भी आपकी है। इसे फिर रिकॉर्ड करें और नई वाली शेयर करें।",
