  "Friend Request notifications are not switched on yet. They start working with the next server update.": "दोस्ती की रिक्वेस्ट के नोटिफ़िकेशन अभी चालू नहीं हैं। अगले सर्वर अपडेट से काम करने लगेंगे।",
  "Direct Message notifications are not switched on yet. They start working with the next server update.": "डायरेक्ट मैसेज के नोटिफ़िकेशन अभी चालू नहीं हैं। अगले सर्वर अपडेट से काम करने लगेंगे।",
  "Riding Group Chat notifications are not switched on yet. They start working with the next server update.": "राइडिंग ग्रुप चैट के नोटिफ़िकेशन अभी चालू नहीं हैं। अगले सर्वर अपडेट से काम करने लगेंगे।",
  "Ride Invites and Leaders You Follow are not switched on yet. They start working with the next server update.": "राइड के न्योते और जिन लीडरों को आप फ़ॉलो करते हैं, अभी चालू नहीं हैं। अगले सर्वर अपडेट से काम करने लगेंगे।",
  "Account notifications are not switched on yet. They start working with the next server update.": "अकाउंट के नोटिफ़िकेशन अभी चालू नहीं हैं। अगले सर्वर अपडेट से काम करने लगेंगे।",
