  "Anyone at the same park shows up here once they switch on Out Riding with Everyone Nearby.": "उसी पार्क में कोई भी, जैसे ही आसपास के सभी के साथ राइड पर चालू करता है, यहाँ दिखता है।",
  "Ridden With You": "आपके साथ राइड की है",
