  "More for {display_name}": "{display_name} के लिए और",
  "Subscriptions are in the OnMyLead app. Pro you buy there works here too.": "सब्सक्रिप्शन OnMyLead ऐप में हैं। वहाँ खरीदा प्रो यहाँ भी चलता है।",
  "Subscriptions open in an upcoming update. Until then your plan stays as it is and nothing is charged.": "सब्सक्रिप्शन आने वाले अपडेट में खुलेंगे। तब तक आपका प्लान वैसा ही रहता है और कुछ चार्ज नहीं होता।",
  "Waiting on {storeName} to approve the purchase.": "{storeName} के खरीद मंज़ूर करने का इंतज़ार है।",
  "The purchase didn’t go through. You weren’t charged.": "खरीद पूरी नहीं हुई। आपसे पैसे नहीं लिए गए।",
  "{v} a Month. Save About {v2}%": "{v} हर महीने। लगभग {v2}% बचाएँ",
  "After you redeem the code in Google Play, come back here and Pro turns on.": "Google Play में कोड रिडीम करने के बाद यहाँ वापस आएँ और प्रो चालू हो जाएगा।",
  ", Best Value": ", सबसे किफ़ायती",
