  "included": "शामिल",
  "not included": "शामिल नहीं",
  "Could not load the ride.": "राइड लोड नहीं हो सकी।",
  "Private, Invite Only": "प्राइवेट, सिर्फ़ न्योते से",
  "Anyone with the Link": "लिंक वाला कोई भी",
  "Everyone who had joined was sent a notification and an email.": "जो भी जुड़े थे, सबको नोटिफ़िकेशन और ईमेल भेज दिया गया।",
  "{v} called it off. You don’t need to do anything.": "{v} ने इसे रद्द कर दिया। आपको कुछ करने की ज़रूरत नहीं।",
  "Request to Join": "शामिल होने की रिक्वेस्ट करें",
  "Sign In to Join": "शामिल होने के लिए साइन इन करें",
  "No waiting for approval: you’re on the list.": "मंज़ूरी का इंतज़ार नहीं: आप लिस्ट में हैं।",
