  "Everyone who joined gets a notification and an email either way. Cancel keeps the ride in their list; delete removes it.": "जो भी जुड़े हैं, उन्हें दोनों हाल में नोटिफ़िकेशन और ईमेल मिलता है। रद्द करने से राइड उनकी लिस्ट में रहती है; डिलीट करने से हट जाती है।",
  "Open Ride Mode to see where you and everyone else are on it.": "राइड मोड खोलें और देखें कि आप और बाकी सब इस पर कहाँ हैं।",
  "Saved on your phone once you’ve opened it, so it’s there without signal.": "एक बार खोलने पर आपके फ़ोन में सेव हो जाती है, ताकि बिना सिग्नल भी मिले।",
  "Edit Route": "रूट एडिट करें",
  "Map a Route Anyway": "फिर भी रूट बनाएँ",
  "Build the Route": "रूट बनाएँ",
  "Mark where the group will stop for fuel, lunch or camp. Every rider sees them numbered on the map, in order.": "मार्क करें कि ग्रुप तेल, खाने या कैंप के लिए कहाँ रुकेगा। हर राइडर मैप पर उन्हें क्रम से नंबर के साथ देखता है।",
  "Mark camp, fuel, a viewpoint or a hazard. Share each one with the whole ride, or keep it to yourself.": "कैंप, तेल, नज़ारा या खतरा मार्क करें। हर एक को पूरी राइड के साथ शेयर करें, या अपने पास रखें।",
  "Mark camp, fuel, a viewpoint or a hazard. Your waypoints are only for you; the leader’s shared ones show here too.": "कैंप, तेल, नज़ारा या खतरा मार्क करें। आपके वेपॉइंट सिर्फ़ आपके लिए हैं; लीडर के शेयर किए हुए भी यहाँ दिखते हैं।",
