  "Imported{v}. Clear it to draw your own.": "इंपोर्ट किया{v}। अपनी खींचने के लिए इसे मिटाएँ।",
  "{v} the map where the ride starts, or Search for the trailhead.": "मैप पर वहाँ {v} जहाँ राइड शुरू होती है, या ट्रेलहेड खोजें।",
  "No mapped trail joins those points, so that part is a straight line. Add a point on the trail or zoom in.": "कोई मैप की हुई ट्रेल उन पॉइंट को नहीं जोड़ती, इसलिए वह हिस्सा सीधी लाइन है। ट्रेल पर पॉइंट जोड़ें या ज़ूम इन करें।",
  "Now {click} further along the trail. The route follows it for you.": "अब ट्रेल पर आगे {click}। रूट आपके लिए उसे फ़ॉलो करता है।",
