  "Straight lines between points. Switch to Follow Trails to snap to the trail.": "पॉइंट के बीच सीधी लाइनें। ट्रेल पर जाने के लिए ट्रेल के साथ पर जाएँ।",
  "Tap a line to see who can ride it.": "किसी लाइन पर टैप करें और देखें कौन उस पर चल सकता है।",
  "Press and hold a line to see who can ride it.": "किसी लाइन को दबाकर रखें और देखें कौन उस पर चल सकता है।",
  "{length} track points": "{length} ट्रैक पॉइंट",
  "Save Route": "रूट सेव करें",
  "Remove Route": "रूट हटाएँ",
  "Couldn’t find your location.": "आपकी लोकेशन नहीं मिल सकी।",
