  "Press and hold": "दबाकर रखें",
  "Join the ride to add and see its waypoints.": "वेपॉइंट जोड़ने और देखने के लिए राइड में शामिल हों।",
  "{drop} the map at {name} to drop {v} there.": "{name} पर मैप को {drop} और वहाँ {v} रखें।",
  "{drop} the map where the group will stop, or Search for the place. Stops are numbered in the order you add them.": "मैप पर वहाँ {drop} जहाँ ग्रुप रुकेगा, या जगह खोजें। स्टॉप उसी क्रम में नंबर पाते हैं जिसमें आप जोड़ते हैं।",
  "{drop} the map to drop a waypoint, or Search for a place. You choose whether the whole ride sees it.": "वेपॉइंट रखने के लिए मैप को {drop}, या जगह खोजें। आप तय करते हैं कि पूरी राइड इसे देखे या नहीं।",
  "{drop} the map to drop a waypoint, or Search for a place. Yours are only for you.": "वेपॉइंट रखने के लिए मैप को {drop}, या जगह खोजें। आपके सिर्फ़ आपके लिए हैं।",
  "Could not copy that ride.": "वह राइड कॉपी नहीं हो सकी।",
  "Trail width limit: {v}. Wider machines won’t fit.": "ट्रेल की चौड़ाई सीमा: {v}। इससे चौड़ी गाड़ियाँ नहीं निकलेंगी।",
  "Checking your invite code. Try again in a second.": "आपका इनवाइट कोड जाँच रहे हैं। एक सेकंड में फिर कोशिश करें।",
  "Pick a different invite code, or clear it to get one made for you.": "दूसरा इनवाइट कोड चुनें, या खाली छोड़ें ताकि आपके लिए बना दिया जाए।",
  "Could not create the ride.": "राइड नहीं बन सकी।",
  "The details, meeting point and route are filled in. Pick the day, check the times and create it.": "डिटेल, मिलने की जगह और रूट भर दिए गए हैं। दिन चुनें, समय जाँचें और बना दें।",
  "The details and meeting point are filled in. Pick the day, check the times and create it.": "डिटेल और मिलने की जगह भर दी गई हैं। दिन चुनें, समय जाँचें और बना दें।",
  "Listed in {name}.": "{name} में लिस्टेड।",
  "Set the meeting point and we fill this in, or pick it.": "मिलने की जगह सेट करें और हम यह भर देंगे, या खुद चुनें।",
  "Fewer Details": "कम डिटेल",
  "Add Route, Difficulty and More": "रूट, कठिनाई और बहुत कुछ जोड़ें",
