  "Create Ride": "राइड बनाएँ",
  "Name Saved": "नाम सेव हो गया",
  "Other riders see you as {shown}": "दूसरे राइडर आपको {shown} के तौर पर देखते हैं",
  "Follow my location": "मेरी लोकेशन फ़ॉलो करें",
