  "Add 1 Hour": "1 घंटा जोड़ें",
  "Your posts, rides, badges and trails show here. Post a ride report to get started.": "आपकी पोस्ट, राइड, बैज और ट्रेल यहाँ दिखती हैं। शुरू करने के लिए राइड रिपोर्ट पोस्ट करें।",
  "Your rides, badges and trails show here. With Pro you can post ride reports and photos too.": "आपकी राइड, बैज और ट्रेल यहाँ दिखती हैं। प्रो के साथ आप राइड रिपोर्ट और फ़ोटो भी पोस्ट कर सकते हैं।",
  "It comes off for everyone.": "यह सबके लिए हट जाता है।",
  "{authorName}’s comment comes off your post for everyone.": "{authorName} का कमेंट आपकी पोस्ट से सबके लिए हट जाता है।",
  "Comments": "कमेंट",
  "Report {authorName}’s comment": "{authorName} के कमेंट की रिपोर्ट करें",
  "No comments yet. Say something.": "अभी कोई कमेंट नहीं। कुछ कहें।",
  "No comments yet.": "अभी कोई कमेंट नहीं।",
  "Comment on {v} {v2}": "{v} {v2} पर कमेंट करें",
  "Your Profile": "आपकी प्रोफ़ाइल",
  "Nothing here yet. Your posts, rides, badges and trails show here.": "यहाँ अभी कुछ नहीं। आपकी पोस्ट, राइड, बैज और ट्रेल यहाँ दिखती हैं।",
  "Nothing from {name} in the last year yet.": "पिछले एक साल में {name} से अभी कुछ नहीं।",
  "Your dish answered but we could not read it. A Starlink software update may have changed things. Try again later.": "आपके डिश ने जवाब दिया पर हम उसे पढ़ नहीं सके। हो सकता है Starlink के सॉफ़्टवेयर अपडेट से कुछ बदल गया हो। बाद में फिर कोशिश करें।",
  "Join your Starlink Wi-Fi and allow OnMyLead to use your local network (Settings › OnMyLead). We keep trying every 10 seconds.": "अपने Starlink Wi-Fi से जुड़ें और OnMyLead को अपना लोकल नेटवर्क इस्तेमाल करने दें (सेटिंग्स › OnMyLead)। हम हर 10 सेकंड में कोशिश करते रहते हैं।",
  "Facing {facing}, {v}° up": "{facing} की ओर, {v}° ऊपर",
