  "Upgrade to Pro": "प्रो पर अपग्रेड करें",
  "Change plans or cancel in Google Play": "Google Play में प्लान बदलें या रद्द करें",
  "Change plans or cancel in your App Store account": "अपने App Store अकाउंट में प्लान बदलें या रद्द करें",
  "Bought Pro on another Android device? Bring it here": "दूसरे Android डिवाइस पर प्रो खरीदा था? उसे यहाँ लाएँ",
  "Bought Pro on another iPhone or iPad? Bring it here": "दूसरे iPhone या iPad पर प्रो खरीदा था? उसे यहाँ लाएँ",
  "Enter an OnMyLead promo code in Google Play": "Google Play में OnMyLead प्रोमो कोड डालें",
  "Enter an OnMyLead offer code from Apple": "Apple का OnMyLead ऑफ़र कोड डालें",
  "Something not working, or a question about OnMyLead? Send us a message with the Contact Us form below, or email {v}, and a real person at {v2} will answer, usually within a day.": "कुछ काम नहीं कर रहा, या OnMyLead के बारे में कोई सवाल है? नीचे संपर्क करें फ़ॉर्म से मैसेज भेजें, या {v} पर ईमेल करें, और {v2} का एक असली इंसान जवाब देगा, आम तौर पर एक दिन के अंदर।",
  "Ask the organizer for the ride code or link, or scan their QR code with your {v} camera. Then tap Join a Ride on the Rides tab.": "आयोजक से राइड कोड या लिंक माँगें, या अपने {v} कैमरे से उनका QR कोड स्कैन करें। फिर राइड टैब में राइड में शामिल हों पर टैप करें।",
  "Refunds are handled by Google Play at play.google.com/store/account/orderhistory.": "रिफ़ंड Google Play संभालता है: play.google.com/store/account/orderhistory।",
  "Refunds are handled by Apple at reportaproblem.apple.com.": "रिफ़ंड Apple संभालता है: reportaproblem.apple.com।",
  "We review every report within 24 hours. For anything urgent, email {v}.": "हम हर रिपोर्ट 24 घंटे के अंदर देखते हैं। किसी ज़रूरी बात के लिए {v} पर ईमेल करें।",
  "Lower {label}": "{label} घटाएँ",
