  "Shows next to your name in rider lists, chat, Messages and Friends.": "राइडर लिस्ट, चैट, मैसेज और दोस्तों में आपके नाम के पास दिखती है।",
  "Add a photo so riders know who’s who. Until then they see your initial.": "फ़ोटो जोड़ें ताकि राइडर जानें कौन कौन है। तब तक वे आपका पहला अक्षर देखते हैं।",
